Lemma art_alloc3_fp_above : forall sp HI t spb ris qs c km ab rz n rs l2 blk q1 q2 x,
  1 <= c <= 30 -> 0 <= km -> 262144 * km <= 3758096384 -> HI <= sp - 1952 -> 0x10007fff8000 <= HI ->
  spb = 65536 * qs -> 0x10007fff8000 <= spb -> ris = spb + 2 ^ 37 -> ris + 4096 <= HI -> t + 4096 <= HI ->
  l2 + 2 ^ 20 <= HI -> blk + 2 ^ 23 <= HI ->
  ab + rz + n <= spb + 2 ^ 37 -> (ab + rz) / 8 = q1 -> rs / 8 = q2 -> 2147450880 + q1 + q2 <= 0x10007fff8000 ->
  sp <= x -> ~ art_alloc3_fp sp t spb ris qs c km ab rz n rs l2 blk x.
